 for l in subprocess.check_output(['nm','-S',str(out/'compiler-split/split/matryoshka.elf') if tag=='split' else str(out/'compiler-context/context/matryoshka.elf') if tag=='context' else str(out/'compiler/cached/matryoshka.elf') if tag=='cached' else str(root/f'build/oracle-integrated-42717665535/{tag}/matryoshka.elf')],text=True).splitlines():
  w=l.split()
  if len(w)==4 and w[2].lower()=='t' and int(w[1],16)>0:symbols.append((int(w[0],16),int(w[1],16),w[3]))
 symbols.sort();addresses=[x[0] for x in symbols];tot=[0]*8;fns=collections.defaultdict(lambda:[0]*8);pcs=[]
 for l in (out/f'{tag}.counts').read_text().splitlines():
